export const source = "'use client';\n\nimport { useRef, useState } from 'react';\nimport { flushSync } from 'react-dom';\n\nimport { IconCircleCheck } from '@tabler/icons-react';\n\nimport {\n  Alert,\n  AlertActions,\n  AlertClose,\n  AlertContent,\n  AlertDescription,\n  AlertIcon,\n  AlertTitle,\n} from '@/components/alert/alert';\nimport { Button } from '@/components/button/button';\n\nexport default function AlertDismissible() {\n  const [open, setOpen] = useState(true);\n  const showRef = useRef<HTMLButtonElement>(null);\n  const closeRef = useRef<HTMLButtonElement>(null);\n\n  function dismiss() {\n    flushSync(() => setOpen(false));\n    showRef.current?.focus();\n  }\n\n  function show() {\n    flushSync(() => setOpen(true));\n    closeRef.current?.focus();\n  }\n\n  if (!open) {\n    return (\n      <Button ref={showRef} variant=\"outline\" onClick={show}>\n        Show alert\n      </Button>\n    );\n  }\n\n  return (\n    <Alert variant=\"success\" layout=\"inline\" className=\"nx:max-w-xl\">\n      <AlertIcon>\n        <IconCircleCheck />\n      </AlertIcon>\n      <AlertContent>\n        <AlertTitle>Import completed</AlertTitle>\n        <AlertDescription>\n          Review the imported contacts before publishing them.\n        </AlertDescription>\n      </AlertContent>\n      <AlertActions>\n        <Button variant=\"outline\">Review</Button>\n        <AlertClose ref={closeRef} onClick={dismiss} />\n      </AlertActions>\n    </Alert>\n  );\n}\n";
